# v631: the Commander's Handbook (How to play remastered). See p631_handbook.js.
import sys, re
P = sys.argv[1] if len(sys.argv) > 1 else 'docs/index.html'
s = open(P, encoding='utf-8').read()
def rep(a, b, n=1):
    global s
    c = s.count(a); assert c == n, (c, a[:90]); s = s.replace(a, b)
js = open('tools/patches/p631_handbook.js', encoding='utf-8').read()
rep('function shHowTo() { return `<div class="hd"><div style="flex:1;min-width:0"><div class="chapter">Etc.</div><h2>How to play</h2></div><button class="x" data-act="close" aria-label="Close">✕</button></div><div class="howto">${mEtc()}${faqHTML()}</div>`; }\n', js)
rep('  howto: () => openSheet({ type: "howto" }), // v279: the Etc. tile', '''  howto: () => { G.hbCh = null; openSheet({ type: "howto" }); }, // v279: the Etc. tile (v631 the Handbook)
  hbCh: d => { G.hbCh = d.k || null; const c = HB.find(x => x.k === d.k); if (c && !hbRead()[c.k]) { S.hbRead = Object.assign({}, S.hbRead, { [c.k]: 1 }); S.shards = (S.shards || 0) + 1; toast(`Chapter read: +◆1`, "win"); dirty(); } render(true); const sc = document.querySelector(".sheet .body, .sheet"); if (sc) sc.scrollTop = 0; document.querySelectorAll(".sheet *").forEach(e => { if (e.scrollTop) e.scrollTop = 0; }); },
  hbShow: d => { const c = HB.find(x => x.k === d.k); if (!c) return; G.hbCh = null; closeSheet(); setTimeout(() => { try { c.show[1](); } catch (e) {} }, 60); },
  hbQ: d => { const q = document.getElementById("faqq"); if (!q) return; q.value = d.q; q.dispatchEvent(new Event("input", { bubbles: true })); q.scrollIntoView({ block: "start", behavior: "smooth" }); },''')
css = ('.hbwrap,.hbpage{display:flex;flex-direction:column;gap:12px}.hbwrap>*,.hbpage>*{flex-shrink:0}'
  '.hbcover{position:relative;display:flex;align-items:center;gap:12px;padding:14px 50px 14px 14px;border-radius:18px;overflow:hidden;background:radial-gradient(120% 140% at 0 0,rgba(56,223,238,.25),transparent 60%),radial-gradient(90% 120% at 100% 100%,rgba(154,123,255,.25),transparent 60%),url(art/celestial-a.jpg) center/cover,#08101c;border:1px solid rgba(127,230,243,.35)}'
  '.hbcover::after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(5,9,16,.2),rgba(5,9,16,.75));z-index:0}.hbcover>*{position:relative;z-index:1}.hbav{width:78px;height:78px;object-fit:cover;object-position:top;border-radius:50%;border:2px solid #38dfee;box-shadow:0 0 20px rgba(56,223,238,.5);flex:none;background:#0a1420}'
  '.hbcover>div{flex:1;min-width:0;display:flex;flex-direction:column;gap:4px}.hbcover small{font-size:10px;letter-spacing:.2em;color:#7fe6f3}.hbcover h2{margin:0;font:800 18px/1.1 var(--f-display);text-wrap:balance}.hbcover p{margin:0;font-size:12px;color:#c9d6ea}.hbcover .x{position:absolute;top:10px;right:10px}'
  '.hbtour{all:unset;box-sizing:border-box;display:flex;align-items:center;gap:12px;padding:12px 14px;border-radius:16px;cursor:pointer;background:linear-gradient(90deg,rgba(5,12,22,.92),rgba(5,12,22,.55)),url(skins/aurora.webp) right -30px center/170px no-repeat,#071019;border:1px solid rgba(79,224,208,.45)}.hbtp{width:42px;height:42px;border-radius:50%;display:grid;place-items:center;background:#4fe0d0;color:#04121a;font-size:16px;box-shadow:0 0 18px rgba(79,224,208,.6);flex:none}.hbtour b{font:700 15px var(--f-display);display:block}.hbtour small{font-size:11.5px;color:#a9c2cc}.hbtour>div{min-width:0;padding-right:70px}'
  '.hbtiles{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.hbtile{all:unset;box-sizing:border-box;position:relative;aspect-ratio:1.35;border-radius:14px;overflow:hidden;cursor:pointer;border:1px solid color-mix(in srgb,var(--c) 45%,transparent);background:#070d16}.hbtile img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:.85;transition:transform .3s}.hbtile:active img{transform:scale(1.06)}'
  '.hbtile span{position:absolute;left:0;right:0;bottom:0;padding:22px 10px 8px;background:linear-gradient(transparent,rgba(4,8,14,.95));display:flex;flex-direction:column}.hbtile small{font-size:10px;letter-spacing:.14em;color:var(--c)}.hbtile b{font:700 14px/1.15 var(--f-display);color:#fff}.hbtile>i{position:absolute;top:7px;right:7px;font-style:normal;font-size:11px;font-weight:800;padding:3px 7px;border-radius:9px;background:rgba(5,10,18,.8);color:#7dffb0;border:1px solid rgba(125,255,176,.5)}.hbtile>i.nw{color:#ffd25a;border-color:rgba(255,210,90,.6)}.hbtile.rd{opacity:.92}'
  '.hbadv{display:flex;gap:10px;align-items:flex-end}.hbadv img{width:46px;height:46px;border-radius:50%;object-fit:cover;object-position:top;border:1.5px solid #38dfee;flex:none;background:#0a1420}.hbadv p{margin:0;padding:9px 12px;border-radius:14px 14px 14px 4px;background:rgba(56,223,238,.12);border:1px solid rgba(56,223,238,.35);font-size:13px;color:#d8eef4}'
  '.hbqc{display:flex;flex-wrap:wrap;gap:6px;margin:2px 0 4px}.hbqc button{all:unset;cursor:pointer;font-size:12px;padding:5px 10px;border-radius:12px;background:rgba(127,230,243,.08);border:1px solid rgba(127,230,243,.3);color:#bfeef6}'
  '.faqi.hbq.on p{margin:0 12px 12px 12px;padding:10px 12px;border-radius:4px 14px 14px 14px;background:rgba(56,223,238,.1);border:1px solid rgba(56,223,238,.3);color:#e1f1f6}'
  '.hbback{align-self:flex-start}.hbhero{position:relative;border-radius:16px;overflow:hidden;aspect-ratio:2.1;border:1px solid color-mix(in srgb,var(--c) 50%,transparent)}.hbhero img{width:100%;height:100%;object-fit:cover}.hbhero>div{position:absolute;left:0;right:0;bottom:0;padding:26px 14px 10px;background:linear-gradient(transparent,rgba(4,8,14,.95));display:flex;flex-direction:column}.hbhero small{font-size:10px;letter-spacing:.16em;color:var(--c)}.hbhero b{font:800 22px var(--f-display)}.hbhero em{position:absolute;top:-150%;right:10px;font-style:normal}.hbhero>div em{position:static;font-size:11px;color:#7dffb0;font-style:normal}'
  '.hbsteps{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:8px}.hbsteps li{display:flex;gap:12px;align-items:flex-start;padding:10px 12px;border-radius:14px;background:rgba(255,255,255,.035);border:1px solid rgba(255,255,255,.07)}.hbsteps li>span{width:40px;height:40px;flex:none;display:grid;place-items:center;font-size:20px;border-radius:12px;background:color-mix(in srgb,var(--c) 18%,#0a111b);border:1px solid color-mix(in srgb,var(--c) 45%,transparent)}.hbsteps p{margin:0;font-size:13.5px;line-height:1.4;color:#cfdbe6;min-width:0}.hbsteps p b{display:block;font-size:10px;letter-spacing:.16em;text-transform:uppercase;color:var(--c);margin-bottom:2px}'
  '.hbchips{display:flex;flex-wrap:wrap;gap:6px}.hbchips span{font-size:12px;font-weight:700;padding:5px 10px;border-radius:12px;color:var(--c);background:color-mix(in srgb,var(--c) 12%,transparent);border:1px solid color-mix(in srgb,var(--c) 45%,transparent)}'
  '.hbctr{padding:10px 12px;border-radius:14px;background:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.07);display:flex;flex-direction:column;gap:6px}.hbsh{font:700 14px var(--f-display)}.hbsh small{font:400 11px var(--f-body);color:var(--muted);margin-left:6px}'
  '.hbcr{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:6px}.hbcr span{display:flex;align-items:center;gap:8px;min-width:0}.hbcr span.t{justify-content:flex-end;text-align:right;flex-direction:row-reverse}.hbcr img{width:42px;height:42px;object-fit:contain;border-radius:10px;background:rgba(255,255,255,.04);flex:none}.hbcr b{font-size:12.5px;line-height:1.2}.hbcr>i{font-style:normal;color:#ff6a5a;font-size:22px;font-weight:900}'
  '.hbwh{display:flex;flex-direction:column;gap:5px}.hbwh span{display:grid;grid-template-columns:1fr auto 1fr;gap:8px;align-items:center;padding:5px 8px;border-radius:10px;background:linear-gradient(90deg,color-mix(in srgb,var(--a) 16%,transparent),color-mix(in srgb,var(--b) 16%,transparent))}.hbwh b{font-size:12.5px}.hbwh b:last-child{text-align:right}.hbwh i{font-style:normal;font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:var(--muted)}'
  '.hbnext{all:unset;box-sizing:border-box;cursor:pointer;display:flex;flex-direction:column;padding:12px 14px;border-radius:14px;border:1px dashed rgba(127,230,243,.35)}.hbnext small{font-size:10px;letter-spacing:.16em;color:#7fe6f3}.hbnext b{font:700 15px var(--f-display)}'
  '.hbpt{position:fixed;z-index:9998;border-radius:14px;border:3px solid #ffd25a;box-shadow:0 0 0 9999px rgba(0,0,0,.35),0 0 24px #ffd25a;pointer-events:none;animation:hbpt 1.1s ease-in-out infinite}.hbpt i{position:absolute;right:-6px;bottom:-34px;font-style:normal;font-size:30px;animation:hbhand .9s ease-in-out infinite}.hbpt b{position:absolute;left:0;bottom:-34px;font-size:13px;padding:5px 10px;border-radius:10px;background:#ffd25a;color:#1a1204;white-space:nowrap}@keyframes hbpt{50%{box-shadow:0 0 0 9999px rgba(0,0,0,.35),0 0 40px #ffd25a}}@keyframes hbhand{50%{transform:translateY(-8px)}}'
  '@media (prefers-reduced-motion:reduce){.hbpt,.hbpt i{animation:none}}\n')
i = s.index('</style>', s.index('#celeb{position:fixed')); s = s[:i] + css + s[i:]
s2 = re.sub(r"GAME_V = 630\b", "GAME_V = 631", s); assert s2 != s; s = s2
open(P, 'w', encoding='utf-8').write(s); print('ok')
